add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','Libellés suisses locaux E04 et sous-codes','OFS Suisse','CIM-10-GM2024',R/'nosology/fragments/S05.json','Entrées E04, E04.0, .1, .2, .8, .9','Classification suisse locale','Métadonnées dérivées ; PDF OFS intégral non relu, pas certification de codage2026.','E04 autres goitres non toxiques : diffus, nodule simple, multinodulaire, autres précisés et sans précision. Correspondance pédagogique PROFILES non officielle.')
add('S2','https://klassifikationen.bfarm.de/icd-10-gm/kode-suche/htmlgm2024/block-e00-e07.htm','Notes de classification E04','BfArM Allemagne','2024','bfarm2024.html','Bloc E00–E07 : E03.0 et ensemble E04','Classification allemande','Pas une recommandation thérapeutique ni édition suisse2026.','Exclure goitres par carence iodée E00–E02 et goitre congénital diffus E03.0. E04.1 inclut nodule kystique ; .2 nodules/kystes multiples ; .8 autre précisé ; .9 sans précision.')
add('S3','https://pmc.ncbi.nlm.nih.gov/articles/PMC10448590/','Clinical practice guidelines for thyroid nodule management','European Thyroid Association','2023','eta-nodules2023.xml','Corps introduction, méthodes, tableau1/notes, tableaux3–6, biologie/échographie/cytologie/moléculaire/imagerie et traitements jusqu’à conclusion','Adultes avec nodules','Pas seuil pédiatrique ; Bethesda tableau2017, troisième édition parue après manuscrit ; performance dépend population. Ne pas reprendre performances commerciales comme validation suisse.','Anamnèse, fonction et échographie ; TSH initiale, hormones selon résultat. EU-TIRADS3>20mm,4>15,5>10 ; ganglion/extension modifie indication. Croissance≥20% dans2diamètres avec minimum2mm ou volume>50%. Pas LT4 systématique en maladie nodulaire euthyroïdienne ni iode/sélénium hors déficit. Surveillance, chirurgie, ablation ou radioiode selon risque, symptômes et préférences ; pas dépistage général asymptomatique.')
add('S4','https://pmc.ncbi.nlm.nih.gov/articles/PMC10542302/','Radioiodine therapy of benign thyroid disease','European Association of Nuclear Medicine','2023','eanm2023.xml','Section non-toxic goiter : définition, indications, contre-indications, préparation, traitement et rhTSH ; sections générales ciblées','Goitre non toxique bénin adulte','Contient contextes carence iodée hors E04 si prouvée, et une incidence textuelle incohérente non reprise. Pas fondement de doses de FI.','Radioiode peut réduire volume40–50% à1an dans séries sélectionnées ; effet retardé, exclure cancer/grossesse/allaitement et besoin de décompression rapide. Volume/fixation guident dosimétrie. rhTSH hors indication et non routinière ; risques gonflement/hypothyroïdie. Suggestion LT4 chez jeunes petits goitres diffère de ETA2023 nodulaire, ne pas inventer consensus.')
add('S5','https://amiko.oddb.org/fr/fi?gtin=7680549490017','Euthyrox : information professionnelle exacte','Swissmedic/AIPS via AmiKo','Février2023','fi-euthyrox.html','Composition, indications, posologie, populations, contre-indications, interactions, grossesse/allaitement, effets et miseàjour','Comprimés25–200µg ; adulte selon indication','Indication de FI goitre bénin euthyroïdien75–200µg/j ne devient pas recommandation de traiter tous nodules ; doses pédiatriques congénitales hors E04 non transposées.','Prise orale à jeun≥30min avant déjeuner, dose individualisée. Risque surtraitement cardiaque/os ; commencer lentement terrain âgé/cardiaque si indication. Résines4–5h après, calcium/fer/aluminium≥2h après LT4, interactions/PPI/soja. Biotine interfère tests. Grossesse substitution nécessaire poursuivie/surveillée, blocage-substitution contreindiqué ; rein/foie pharmacocinétique non étudiée.')
add('S6','https://amiko.oddb.org/fr/fi?gtin=7680527280012','Sodium iodide (I-131) capsule T Curium','Swissmedic/AIPS via AmiKo','Juillet2022','fi-sodium-iodide131.html','Indication, posologie, rein/enfant, contre-indications, sécurité/interactions, grossesse/allaitement, miseàjour ; pas tables dosimétriques tousorganes reprises','Gélule thérapeutique orale37–7400MBq à calibration','Plage de présentation non dose standard E04. Texte interne2jours versus3jours carbimazole et conseils conception6–12mois versus contraception6mois bénin : ne pas harmoniser, plan spécialisé. Ne pas certifier stock2026.','Indication inclut goitre euthyroïdien ; activité individualisée selon volume/fixation/clairance, effet plusieurs semaines. Hypothyroïdie, thyroïdite/gonflement, glandes salivaires. Grossesse et allaitement contreindiqués, sevrage≥8semaines sans reprise pour cet enfant. Dysphagie/sténoses digestives contreindiquent cette capsule. Rein : irradiation accrue, pas simple dose fixe. Médicaments/iode/contraste modifient fixation, pas arrêt autonome.')
add('S7','https://www.bag.admin.ch/dam/fr/sd-web/vsVYUlb8caju/V2_250624_Strahlenschutz_Wegleitung_Radionuklidtherapie_FR.pdf','Radiothérapie métabolique','OFSP Suisse','V2,24juin2025','swiss-radionuclide2025.pdf','p1–4, tableau1 et1.1–1.5','Radioprotection en Suisse','Directive de radioprotection, pas FI ni indication clinique. Pas extrapolation des règles Lu177 au131.','Calcul individuel documenté. Iode131 résidentiel dès200MBq,48hmin et débit<10µSv/h à1m ; exceptions ambulatoires200–400 autorisation OFSP préalable, pas fractionnement pour éviter hospitalisation. Informations orales/écrites de sortie et protection entourage.')
add('S8','https://www.blv.admin.ch/de/jodiertes-salz','Sel iodé','OSAV Suisse','Page consultée2nov2026','swiss-iodised-salt.html','Corps entier, stratégie iodation et alimentation','Population suisse','Page grandpublic, pas incidence E04 ni justification supplément à tous ; dates de pièces jointes non dates de nouvelle recommandation.','Sel iodé25mg/kg ; remplacer le sel utilisé sans augmenter quantité. Iodation volontaire, alimentation et produits transformés influencent apport ; algues apport variable/excessif. Les goitres ne disparaissent pas tous avec iodation.')
add('S9','https://www.blv.admin.ch/de/monitoring-jod-versorgung-der-schweizer-bevoelkerung','Monitoring de la couverture iodée suisse','OSAV Suisse','Enquête2020–2022, page consultée2026','swiss-iodine-monitoring.html','Corps entier, échantillons/médianes et limites','362enfants6–12ans et473femmes enceintes','Statut populationnel, pas incidence goitre, pas diagnostic individuel par spot ; moyenne normale fonction ne prouve pas suffisance iodée de toute grossesse.','Médiane iodurie127µg/l chez enfants et97chez femmes enceintes ; supplémentation déclarée47%, médianes88sans/140avec. Ne pas dire toutes femmes supplémentées suffisantes ; prévention contextualisée.')
add('S10','https://www.blv.admin.ch/de/jodtabletten-fuer-stillende-muetter-und-die-jodversorgung-von-saeuglingen','Iode chez mère allaitante et nourrisson','OSAV Suisse','Étude2021–2024, page consultée2026','swiss-lactation-iodine.html','Corps entier et taille/population étude','17paires mère-enfant','Petit essai et information institutionnelle, pas publication indépendante relue ni dose0–300µg recommandée.','Apport total recommandé250µg/j pendant allaitement sur données limitées ; OSAV conseille poursuivre complément iodé commencé en grossesse. Vérifier tout apport et terrain thyroïdien, ne pas appeler250une dose de comprimé universelle.')
add('S11','https://www.blv.admin.ch/dam/de/sd-web/DknRSfuZymhE/faq-jod-supplement-de.pdf','FAQ supplémentation iodée','OSAV Suisse','Octobre2024','swiss-iodine-faq2024.pdf','Deux pages entières','Alimentation et maladies thyroïdiennes','Upload2026 ne renouvelle pas version2024 ; restriction temporaire pré-radioiode distincte de régime courant.','Pas augmentation du sel ; sels marins non enrichis bien moins iodés. Réaction au contraste n’est pas allergie à tout iode alimentaire ; ne pas prescrire éviction universelle sur maladie thyroïdienne.')
add('S12','https://pmc.ncbi.nlm.nih.gov/articles/PMC8314764/','Iodine-based contrast media-induced thyroid dysfunction','European Thyroid Association','2021','/tmp/medina-source-cache/endocrinologie/E01/eta2021-web-passages.json','Passages PMC lignes147–343 : méthode, recommandations1–22, facteurs, surveillance','Adultes exposés contraste, surtout risque nodulaire/cardiaque','Passages textuels réellement relus, pas HTML homonyme qui contient CAPTCHA. Pas doses antithyroïdiennes copiées sans FI.','Pas bilan systématique population avant/après contraste ; bilan TSH ciblé sujet à risque, hormones si bas. Fonction normale n’exclut pas autonomie. Prévention médicamenteuse non universelle, avis spécialisé. Hautrisque contrôle3–4semaines ; différer scintigraphie/radioiode1–2mois après contraste selon contexte.')
add('S13','https://pmc.ncbi.nlm.nih.gov/articles/PMC9716393/','Pediatric thyroid nodules and differentiated thyroid carcinoma','European Thyroid Association','2022','/tmp/medina-source-cache/endocrinologie/E01/eta-pediatrie2022.xml','Méthode, tableau3 partieB, sectionsB1–B2 et tableau5 génétique, recommandations3/4/7','Moins18ans','Guide européen ayant repris certaines opinions ATA2015 déclarées niveau4 ; pas conduite fondée directement sur recommandation américaine. Seuils adultes non transposables.','Échographie cou complète, critères multiples et cytologie si suspicion ; suivi nodules bénins et nouvelle ponction si modification. Goitre multinodulaire possible DICER1/PTEN, pas dépistage génétique de tout adulte. Orientation équipe pédiatrique spécialisée.')
add('S14','https://openstax.org/books/anatomy-and-physiology-2e/pages/17-4-the-thyroid-gland','Thyroid gland : science normale','OpenStax','AnatomyPhysiology2e','/tmp/medina-source-cache/endocrinologie/E35/openstax-thyroid.html','Anatomie, follicule, synthèse/rétrocontrôle et légende17.12 réellement relus','Normal humain','Manuel américain pour science normale seulement, pas recommandations cliniques ; raccourcis étiologiques pathologiques non repris.','Deux lobes/isthme avant trachée, parathyroïdes surtout arrière ; follicule colloïde/thyroglobuline, cellules folliculaires et C. Captation/organification/couplage puis libération hormones ; rétrocontrôle hypophyse. MicrographieMichigan©2012 optique1332, pas calibration écran/coloration établie.')
add('S15','https://commons.wikimedia.org/wiki/File:1811_The_Thyroid_Gland.jpg','Notice propre image1811','OpenStax College, Connexions','19juin2013','normal-thyroid-license.json','Métadonnées auteur/crédit/licence, original555506octets réellement inspecté','Planche normale humaine avec micrographie','Un original distinct réutilisé2fois, pas biopsie E04 ni figure échographique de risque ; anglais original, repères FR superposés sans pixels modifiés.','CC BY3.0 propre à la planche, auteurOpenStaxCollege, sourceConnexions. Anatomie et micrographie normales, pas image générée.','license_metadata')
add('S16','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','PROFILES','CIMS Suisse','2017','/workspace/medina-source-cache/C85/profiles2017-official.pdf','EPA2m/2n p18, SSP37 et163','Formation fédérale suisse','Pas correspondance CIMofficielle ni prédiction question.','Inspection/palpation structures cervicales et thyroïde ; situation gonflement cou/goitre et hormones thyroïdiennes anormales. Lien pédagogique à bilan fonction/structure/urgence.')
